package dev.konqasasas.beat.application;
import dev.konqasasas.beat.domain.CompetitionKind;import dev.konqasasas.beat.domain.ta.TimeAttackSession;import dev.konqasasas.beat.persistence.*;import dev.konqasasas.beat.persistence.snapshot.*;import java.util.*;
public final class TimeAttackResultService {private final ResultsRepository repository;public TimeAttackResultService(ResultsRepository r){repository=r;}public ResultsSnapshot saveFinal(TimeAttackSession s)throws PersistenceException{ResultsSnapshot c=repository.load().orElse(new ResultsSnapshot(1,false,false,false,false,List.of()));Map<UUID,PlayerResultSnapshot> old=new LinkedHashMap<>();c.players().forEach(p->old.put(p.uuid(),p));List<PlayerResultSnapshot> out=new ArrayList<>();s.rankings().forEach(e->{var p=old.remove(e.competitor().uuid());var r=e.record();out.add(new PlayerResultSnapshot(e.competitor().uuid(),e.competitor().tournamentName(),p!=null&&p.participatedHigh(),e.competitor().participatedIn(CompetitionKind.TIME_ATTACK),p!=null&&p.participatedEndurance(),p!=null&&p.overallExcluded(),p!=null&&p.disqualified(),p==null?null:p.high(),new TimeAttackResultSnapshot(e.rank(),opt(r.personalBestTicks()),opt(r.personalBestRecordedTick()),opt(r.personalBestRecordSequence()),opt(r.personalBestSplit1Ticks()),opt(r.personalBestSplit2Ticks())),p==null?null:p.endurance(),null));});out.addAll(old.values());var saved=new ResultsSnapshot(c.schemaVersion(),c.highConfirmed(),true,c.enduranceConfirmed(),false,out);repository.save(saved);return saved;}public ResultsSnapshot current()throws PersistenceException{return repository.load().orElse(new ResultsSnapshot(1,false,false,false,false,List.of()));}private static Long opt(java.util.OptionalLong v){return v.isPresent()?v.getAsLong():null;}}
